    public static Torque Average(this IEnumerable<Torque> values)
    {
        double sum = 0; long count = 0;
        foreach (var v in values) { sum += v.SI; count++; }
        return count == 0 ? throw new InvalidOperationException("Sequence contains no elements") : Torque.FromSI(sum / count);
    }

    public static Torque Min(this IEnumerable<Torque> values) => Aggregate(values, Math.Min);
    public static Torque Max(this IEnumerable<Torque> values) => Aggregate(values, Math.Max);

    private static Torque Aggregate(IEnumerable<Torque> values, Func<double, double, double> pick)
    {
        using var e = values.GetEnumerator();
        if (!e.MoveNext()) throw new InvalidOperationException("Sequence contains no elements");
        var result = e.Current.SI;
        while (e.MoveNext()) result = pick(result, e.Current.SI);
        return Torque.FromSI(result);
    }
}
